ALTER TABLE expert_residency_orders DROP CONSTRAINT expert_order_credit_cap, ADD CONSTRAINT expert_order_policy_version CHECK (commercial_policy_version IN ('legacy_residency_v1','expert_residency_v2')), ADD CONSTRAINT expert_order_credit_cap CHECK (credit_cap_bps BETWEEN 0 AND 10000 AND credit_minor*10000 <= price_minor*credit_cap_bps), ADD CONSTRAINT expert_order_v2_cap CHECK (commercial_policy_version <> 'expert_residency_v2' OR credit_cap_bps=3000), ADD CONSTRAINT expert_order_group_event_limit CHECK (group_event_limit BETWEEN 0 AND 3), ADD CONSTRAINT expert_order_statistics_level CHECK (statistics_level IN ('basic','expanded')), ADD CONSTRAINT expert_order_support_priority CHECK (support_priority IN ('standard','priority')), ADD CONSTRAINT expert_order_cash_credit_conservation CHECK (cash_minor+credit_minor=price_minor);
